/**
 * Ensures amplify_outputs.json exists before tsc/vite build.
 *
 * In a real AWS Amplify deployment, this file is generated by
 * `npx ampx pipeline-deploy`. For local development and CI builds
 * that run without AWS credentials (e.g. PR lint/test/build gate),
 * we fall back to the committed CI stub so TypeScript and Vite can
 * resolve the import in src/main.tsx.
 *
 * The copied stub contains placeholder values only — it is never
 * used at runtime in production.
 */
import { existsSync, copyFileSync } from 'node:fs';

const OUTPUT = 'amplify_outputs.json';
const STUB   = 'amplify_outputs.ci.json';

if (!existsSync(OUTPUT)) {
  if (!existsSync(STUB)) {
    console.error(`[setup-amplify-outputs] error: ${OUTPUT} not found and no CI stub (${STUB}) available.`);
    process.exit(1);
  }
  copyFileSync(STUB, OUTPUT);
  console.log(`[setup-amplify-outputs] ${OUTPUT} not found — using ${STUB} as build stub`);
}
